12	// chdirTemp 切换到全新的临时目录，避免测试触碰真实的 ledger.json。
13	func chdirTemp(t *testing.T) string {
14		t.Helper()
15		dir := t.TempDir()
16		orig, err := os.Getwd()
17		if err != nil {
18			t.Fatalf("取工作目录: %v", err)
19		}
20		if err := os.Chdir(dir); err != nil {
21			t.Fatalf("切换临时目录: %v", err)
22		}
23		t.Cleanup(func() { _ = os.Chdir(orig) })
24		return dir
25	}
