72	// 子命令之后给出 -f 时，记录必须落到该文件，而不是默认 ledger.json。
73	func TestFileFlagAfterSubcommandSelectsTarget(t *testing.T) {
74		dir := chdirTemp(t)
75		target := filepath.Join(dir, "other.json")
76	
77		r := runArgs(t, "register", "--id", "M-1", "--name", "万用表",
78			"--allowed", "0.5", "-f", target)
79		if r.code != 0 {
80			t.Fatalf("register 退出码 %d，stderr=%s", r.code, r.stderr)
81		}
82		if !fileExists(t, target) {
83			t.Fatal("子命令后的 -f 未让记录进入指定文件")
84		}
85		if fileExists(t, filepath.Join(dir, "ledger.json")) {
86			t.Fatal("误创建了默认 ledger.json")
87		}
88	
89		lr := runArgs(t, "list", "-f", target)
90		if lr.code != 0 || !strings.Contains(lr.stdout, "M-1") {
91			t.Fatalf("从指定文件查询失败 code=%d stdout=%q", lr.code, lr.stdout)
92		}
93	}
