95	// 多个文件参数交错出现时，按命令行顺序以最后一次为准。
96	func TestMultipleFileFlagsLastWins(t *testing.T) {
97		dir := chdirTemp(t)
98		a := filepath.Join(dir, "a.json")
99		b := filepath.Join(dir, "b.json")
100		c := filepath.Join(dir, "含 空格 的目录", "c.json")
101	
102		r := runArgs(t,
103			"-f", a,
104			"register",
105			"--id", "M-1",
106			"--file", b,
107			"--name", "万用表",
108			"--allowed", "0.5",
109			"-f", c,
110		)
111		if r.code != 0 {
112			t.Fatalf("register code=%d stderr=%s", r.code, r.stderr)
113		}
114		if fileExists(t, a) || fileExists(t, b) {
115			t.Fatal("被覆盖的文件路径不应被创建或读取")
116		}
117		if !fileExists(t, c) {
118			t.Fatal("最后一次指定的路径才应是目标台账")
119		}
120	
121		// 短名与长名混合、按命令行顺序覆盖：中间给过不存在的路径，最后一次
122		// 落在真正有数据的 c；再验证最后一次落到空路径时不会回头使用 c。
123		none := filepath.Join(dir, "none.json")
124		r2 := runArgs(t, "list", "--file", a, "-f", none, "--file", c)
125		if r2.code != 0 || !strings.Contains(r2.stdout, "M-1") {
126			t.Fatalf("短长名混合的 last-wins 查询失败 code=%d stdout=%q", r2.code, r2.stdout)
127		}
128		r3 := runArgs(t, "list", "-f", c, "--file", none)
129		if r3.code != 0 || strings.Contains(r3.stdout, "M-1") {
130			t.Fatalf("最后一次为空路径时不应再使用前面的 c，stdout=%q", r3.stdout)
131		}
132		if fileExists(t, none) {
133			t.Fatal("查询不应创建仅作为中间值出现过的文件")
134		}
135	}
