	def := filepath.Join(dir, "ledger.json")
	if err := os.WriteFile(def, []byte("坏"), 0o644); err != nil {
		t.Fatal(err)
	}
	r = runArgs(t, "list")
	if r.code != 2 || !strings.Contains(r.stderr, "ledger.json") {
