	r := runArgs(t, args...)
	if r.code != 2 {
		t.Fatalf("末尾缺值应退出 2，得到 %d", r.code)
	}
	rv := runArgs(t, "review", "--id", "M-1", "-f", target, "--json")
	if !strings.Contains(rv.stdout, `"history": []`) &&
